const ctx = $('Begin Alignment').first().json;
const trigger = $('When Executed by Another Workflow').first().json;
const response = $json ?? {};

const body =
  response.body && typeof response.body === 'object' && !Array.isArray(response.body)
    ? response.body
    : response;

let statusCode = Number(response.statusCode ?? response.status ?? 0);
if (!statusCode && body.status === 'ready') statusCode = 201;

const jobId = String(trigger.job_id ?? '').trim();
const runId = String(ctx.alignment_run_id ?? '').trim();
const expectedAudioSha = String(ctx.audio_sha256 ?? '').trim().toLowerCase();
const expectedDuration = Number(ctx.audio_duration_ms);
const expectedLanguage = String(ctx.language_code ?? '').trim();
const expectedModelSha =
  '60ed5bc3dd14eea856493d334349b405782ddcaf0028d4b5df4088345fba2efe';
const expectedImageDigest =
  'sha256:9cfbaf11ef5bec57ec9cade6af7ed991ab5e32b01a6e40db3380a12363336e11';
const expectedAlignmentPath = '/data/alignments/' + jobId + '/final.json';
const expectedRawPath = '/data/alignments/' + jobId + '/whisper.json';

let scenes = ctx.scenes_json;
if (typeof scenes === 'string') {
  try { scenes = JSON.parse(scenes); } catch { scenes = []; }
}
if (!Array.isArray(scenes)) scenes = [];

const timings = Array.isArray(body.scene_timings) ? body.scene_timings : [];
const expectedSceneIds = new Set(
  scenes.map((scene) => String(scene?.scene_uuid ?? '').trim().toLowerCase())
);

const seen = new Set();
let previousEnd = 0;
let timingsValid = timings.length === scenes.length && timings.length > 0;

for (const timing of timings) {
  const sceneId = String(timing?.scene_uuid ?? '').trim().toLowerCase();
  const startMs = Number(timing?.start_ms);
  const endMs = Number(timing?.end_ms);
  const coverage = Number(timing?.coverage);

  if (
    !expectedSceneIds.has(sceneId) ||
    seen.has(sceneId) ||
    !Number.isInteger(startMs) ||
    !Number.isInteger(endMs) ||
    startMs < previousEnd ||
    endMs <= startMs ||
    endMs > expectedDuration ||
    coverage !== 1
  ) {
    timingsValid = false;
    break;
  }

  seen.add(sceneId);
  previousEnd = endMs;
}

if (seen.size !== expectedSceneIds.size) timingsValid = false;

const alignmentSuccess =
  statusCode === 201 &&
  body.status === 'ready' &&
  String(body.job_id ?? '').trim() === jobId &&
  String(body.audio_sha256 ?? '').trim().toLowerCase() === expectedAudioSha &&
  Number(body.audio_duration_ms) === expectedDuration &&
  String(body.language_code ?? '').trim() === expectedLanguage &&
  String(body.model_sha256 ?? '').trim().toLowerCase() === expectedModelSha &&
  String(body.whisper_image_digest ?? '').trim() === expectedImageDigest &&
  body.normalized_match === true &&
  Number(body.global_coverage) === 1 &&
  Number.isInteger(Number(body.lexical_token_count)) &&
  Number(body.lexical_token_count) > 0 &&
  Number.isInteger(Number(body.lexical_start_ms)) &&
  Number(body.lexical_start_ms) >= 0 &&
  Number.isInteger(Number(body.lexical_end_ms)) &&
  Number(body.lexical_end_ms) > Number(body.lexical_start_ms) &&
  Number(body.lexical_end_ms) <= expectedDuration &&
  String(body.alignment_path ?? '').trim() === expectedAlignmentPath &&
  String(body.raw_whisper_path ?? '').trim() === expectedRawPath &&
  typeof body.transcript === 'string' &&
  body.transcript.trim().length > 0 &&
  timingsValid;

const providerMessage =
  body?.message ??
  body?.error ??
  response?.error?.message ??
  response?.message ??
  'local alignment result failed validation';

return {
  json: {
    job_id: jobId,
    alignment_run_id: runId,
    alignment_success: alignmentSuccess,
    result: alignmentSuccess ? body : {},
    error_message: alignmentSuccess ? '' : String(providerMessage).slice(0, 3500),
  },
};

const ctx = $('Begin Alignment').first().json;
const source = $json ?? {};
const errorObject =
  source.error && typeof source.error === 'object' && !Array.isArray(source.error)
    ? source.error
    : {};

const message = [
  source.error_message,
  errorObject.message,
  source.message,
  source.description,
  typeof source.error === 'string' ? source.error : null,
].find((value) => typeof value === 'string' && value.trim().length > 0)
  ?? 'unspecified M7 alignment failure';

return {
  json: {
    alignment_run_id: String(ctx.alignment_run_id ?? '').trim(),
    error_message: ('M7 local alignment failed: ' + message.trim()).slice(0, 4000),
  },
};
